    @Test
    public void nullPoolIsRejectedBeforeAnyChannelInteraction() {
        TestSourceConduit sourceConduit = new TestSourceConduit().data("ignored");
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit();
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        RecordingExceptionHandler readHandler = new RecordingExceptionHandler();
        RecordingExceptionHandler writeHandler = new RecordingExceptionHandler();

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> Transfer.initiateTransfer(source, sink, null, null, readHandler, writeHandler, null));

        assertTrue(exception.getMessage().contains("pool"),
                "exception message should name the offending argument: " + exception.getMessage());
        assertTrue(exception.getMessage().contains("cannot be null"),
                "exception message should explain the problem: " + exception.getMessage());
        assertEquals(0, sourceConduit.readCalls, "no read may be attempted when the pool is null");
        assertEquals(0, sinkConduit.writeCalls, "no write may be attempted when the pool is null");
        assertEquals(0, source.readListenerInvocations());
        assertNull(source.getReadListener(), "no listener may be installed when the pool is null");
        assertNull(sink.getWriteListener(), "no listener may be installed when the pool is null");
        assertEquals(0, readHandler.count);
        assertEquals(0, writeHandler.count);
    }

