    @Test
    public void immediateEofCompletesTransferAndReleasesBuffer() {
        TestSourceConduit sourceConduit = new TestSourceConduit().eof();
        ConduitStreamSourceChannel source = sourceChannel(sourceConduit);
        TestSinkConduit sinkConduit = new TestSinkConduit();
        ConduitStreamSinkChannel sink = sinkChannel(sinkConduit);
        TestByteBufferPool pool = new TestByteBufferPool(16, false);
        RecordingListener sourceListener = new RecordingListener();
        RecordingListener sinkListener = new RecordingListener();
        RecordingExceptionHandler readHandler = new RecordingExceptionHandler();
        RecordingExceptionHandler writeHandler = new RecordingExceptionHandler();

        Transfer.initiateTransfer(source, sink, sourceListener, sinkListener, readHandler, writeHandler, pool);

        assertEquals(1, pool.allocateCount, "exactly one buffer must be allocated");
        assertEquals(1, pool.closeCount, "the buffer must be released when the transfer finished inline");
        assertEquals(0, pool.openCount());
        assertEquals(1, sourceConduit.readCalls);
        assertEquals(0, sinkConduit.writeCalls, "nothing must be written when the source is empty");
        assertEquals(0, sinkConduit.writtenSize());
        assertEquals(1, sourceConduit.wakeupReadsCalls, "the source listener must be woken up");
        assertEquals(0, sourceConduit.suspendReadsCalls, "the source must not be suspended when a listener is given");
        assertEquals(1, sinkConduit.wakeupWritesCalls, "the sink listener must be woken up");
        assertEquals(0, sinkConduit.suspendWritesCalls, "the sink must not be suspended when a listener is given");
        assertSame(sourceListener, source.getReadListener(), "the user read listener must be installed");
        assertSame(sinkListener, sink.getWriteListener(), "the user write listener must be installed");
        assertEquals(0, readHandler.count);
        assertEquals(0, writeHandler.count);
    }

